UPDATE HR_REWARD T SET (T.ACTIVITY, T.UPDATED_DATE, T.UPDATED_BY, T.UPDATED_IP
) = (SELECT 0, A.CREATE_DATE, A.CREATED_BY, A.CREATED_IP
FROM HR_REWARD_APPLY A WHERE A.REWARD_NO=#REWARD_NO# ) WHERE T.REWARD_NO=#UPDATE_REWARD_NO#
